-- LINE assigns the same user ID to channels within a provider.
-- Retain the original UNIQUE column as row storage to keep friends.id and its child rows intact.
-- Existing LINE IDs stay verbatim. A new row can use musubo-scope:<friend id>:<LINE user ID>.
ALTER TABLE friends ADD COLUMN line_platform_user_id TEXT GENERATED ALWAYS AS (
  CASE
    WHEN substr(line_user_id, 1, length('musubo-scope:' || id || ':')) = 'musubo-scope:' || id || ':'
      THEN substr(line_user_id, length('musubo-scope:' || id || ':') + 1)
    ELSE line_user_id
  END
) VIRTUAL;

CREATE UNIQUE INDEX friends_account_platform_uid
  ON friends(line_account_id, line_platform_user_id);
CREATE UNIQUE INDEX friends_unassigned_platform_uid
  ON friends(line_platform_user_id) WHERE line_account_id IS NULL;
CREATE INDEX friends_platform_uid_lookup ON friends(line_platform_user_id);

-- Reservation and delivery triggers use the LINE-facing ID of the scoped friend.
DROP TRIGGER booking_waitlist_registration;
CREATE TRIGGER booking_waitlist_registration BEFORE INSERT ON booking_waitlist BEGIN SELECT CASE WHEN julianday(NEW.starts_at)<=julianday('now','+1 hour') THEN RAISE(ABORT,'waitlist_registration_closed') WHEN ((SELECT COUNT(*) FROM booking_waitlist w WHERE w.line_account_id=NEW.line_account_id AND w.status IN ('waiting','invited') AND (w.friend_id=NEW.friend_id OR (w.booking_customer_id IS NOT NULL AND w.booking_customer_id=NEW.booking_customer_id))) + (SELECT COUNT(*) FROM rt_seat_waitlist w JOIN rt_stores s ON s.id=w.store_id WHERE s.line_account_id=NEW.line_account_id AND w.status IN ('waiting','invited') AND w.line_uid=(SELECT line_platform_user_id FROM friends WHERE id=NEW.friend_id AND line_account_id=NEW.line_account_id)))>=3 THEN RAISE(ABORT,'waitlist_limit') END; END;

DROP TRIGGER event_booking_transition_version;
CREATE TRIGGER event_booking_transition_version AFTER UPDATE OF status,slot_id,friend_id,line_account_id,participation_mode ON event_bookings WHEN NEW.status IS NOT OLD.status OR NEW.slot_id IS NOT OLD.slot_id OR NEW.friend_id IS NOT OLD.friend_id OR NEW.line_account_id IS NOT OLD.line_account_id OR NEW.participation_mode IS NOT OLD.participation_mode BEGIN  UPDATE event_bookings SET lock_version=OLD.lock_version+1 WHERE id=NEW.id;  INSERT INTO event_booking_transition_runs  (id,line_account_id,event_id,booking_id,booking_id_history,expected_booking_version,booking_version,event_version,operation_key,action,input_snapshot,before_json,after_json,created_at,updated_at)  SELECT lower(hex(randomblob(16))),NEW.line_account_id,NEW.event_id,NEW.id,NEW.id,OLD.lock_version,OLD.lock_version+1,e.current_published_version_id,  'event-transition:'||NEW.id||':'||(OLD.lock_version+1),  CASE WHEN NEW.slot_id<>OLD.slot_id THEN 'change' WHEN NEW.status='cancelled' THEN 'cancel' WHEN NEW.status='rejected' THEN 'reject' ELSE NEW.status END,  json_object('friendId',NEW.friend_id,'recipient',f.line_platform_user_id,'slotId',NEW.slot_id,'startsAt',s.starts_at,'status',NEW.status,'eventName',e.name,'venueName',e.venue_name,'venueUrl',e.venue_url,'cancelledBy',NEW.cancelled_by),  json_object('status',OLD.status,'slotId',OLD.slot_id,'version',OLD.lock_version),  json_object('status',NEW.status,'slotId',NEW.slot_id,'version',OLD.lock_version+1),  strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')  FROM events e JOIN event_slots s ON s.id=NEW.slot_id JOIN friends f ON f.id=NEW.friend_id WHERE e.id=NEW.event_id; END;

DROP TRIGGER event_slot_transition_generations;
CREATE TRIGGER event_slot_transition_generations AFTER UPDATE OF starts_at,ends_at ON event_slots WHEN NEW.starts_at IS NOT OLD.starts_at OR NEW.ends_at IS NOT OLD.ends_at BEGIN  UPDATE event_bookings SET lock_version=lock_version+1 WHERE slot_id=NEW.id AND status IN('requested','confirmed');  INSERT INTO event_booking_transition_runs  (id,line_account_id,event_id,booking_id,booking_id_history,expected_booking_version,booking_version,event_version,operation_key,action,input_snapshot,before_json,after_json,created_at,updated_at)  SELECT lower(hex(randomblob(16))),b.line_account_id,b.event_id,b.id,b.id,b.lock_version-1,b.lock_version,e.current_published_version_id,  'event-transition:'||b.id||':'||b.lock_version,'schedule_changed',  json_object('friendId',b.friend_id,'recipient',f.line_platform_user_id,'slotId',b.slot_id,'startsAt',NEW.starts_at,'status',b.status,'eventName',e.name,'venueName',e.venue_name,'venueUrl',e.venue_url),  json_object('startsAt',OLD.starts_at,'endsAt',OLD.ends_at,'version',b.lock_version-1),  json_object('startsAt',NEW.starts_at,'endsAt',NEW.ends_at,'version',b.lock_version),  strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')  FROM event_bookings b JOIN events e ON e.id=b.event_id JOIN friends f ON f.id=b.friend_id  WHERE b.slot_id=NEW.id AND b.status IN('requested','confirmed'); END;

DROP TRIGGER event_venue_transition_generations;
CREATE TRIGGER event_venue_transition_generations AFTER UPDATE OF venue_name,venue_url ON events WHEN NEW.venue_name IS NOT OLD.venue_name OR NEW.venue_url IS NOT OLD.venue_url BEGIN  UPDATE event_bookings SET lock_version=lock_version+1 WHERE event_id=NEW.id AND status IN('requested','confirmed');  INSERT INTO event_booking_transition_runs  (id,line_account_id,event_id,booking_id,booking_id_history,expected_booking_version,booking_version,event_version,operation_key,action,input_snapshot,before_json,after_json,created_at,updated_at)  SELECT lower(hex(randomblob(16))),b.line_account_id,b.event_id,b.id,b.id,b.lock_version-1,b.lock_version,e.current_published_version_id,  'event-transition:'||b.id||':'||b.lock_version,'schedule_changed',  json_object('friendId',b.friend_id,'recipient',f.line_platform_user_id,'slotId',b.slot_id,'startsAt',s.starts_at,'status',b.status,'eventName',e.name,'venueName',e.venue_name,'venueUrl',e.venue_url),  json_object('venueName',OLD.venue_name,'venueUrl',OLD.venue_url,'version',b.lock_version-1),  json_object('venueName',NEW.venue_name,'venueUrl',NEW.venue_url,'version',b.lock_version),  strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')  FROM event_bookings b JOIN events e ON e.id=b.event_id JOIN event_slots s ON s.id=b.slot_id JOIN friends f ON f.id=b.friend_id  WHERE b.event_id=NEW.id AND b.status IN('requested','confirmed'); END;

DROP TRIGGER meet_run_snapshot;
CREATE TRIGGER meet_run_snapshot AFTER INSERT ON meet_consultation_notification_runs WHEN NEW.retry_key='' BEGIN UPDATE meet_consultation_notification_runs SET retry_key=NEW.id,booking_id=(SELECT booking_id FROM meet_consultations WHERE id=NEW.consultation_id),booking_version=(SELECT booking_version FROM meet_consultations WHERE id=NEW.consultation_id),line_account_id=(SELECT f.line_account_id FROM meet_consultations c JOIN friends f ON f.id=c.friend_id WHERE c.id=NEW.consultation_id),friend_id=(SELECT friend_id FROM meet_consultations WHERE id=NEW.consultation_id),recipient_id=(SELECT f.line_platform_user_id FROM meet_consultations c JOIN friends f ON f.id=c.friend_id WHERE c.id=NEW.consultation_id),starts_at=(SELECT starts_at FROM meet_consultations WHERE id=NEW.consultation_id),ends_at=(SELECT ends_at FROM meet_consultations WHERE id=NEW.consultation_id),meet_url=(SELECT meet_url FROM meet_consultations WHERE id=NEW.consultation_id),schedule_revision=(SELECT schedule_revision FROM meet_consultations WHERE id=NEW.consultation_id) WHERE id=NEW.id; END;

DROP TRIGGER rt_dining_snapshot_insert;
CREATE TRIGGER rt_dining_snapshot_insert AFTER INSERT ON rt_reservations WHEN NEW.dining_snapshot_json IS NULL BEGIN UPDATE rt_reservations SET dining_snapshot_json=json_object( 'allergy',COALESCE(NEW.allergy_note,(SELECT v.value FROM friend_field_values v JOIN friends f ON f.id=v.friend_id JOIN rt_stores s ON s.line_account_id=f.line_account_id WHERE s.id=NEW.store_id AND f.line_platform_user_id=NEW.line_uid AND v.field_id='fixed-allergy' LIMIT 1)), 'anniversary',(SELECT v.value FROM friend_field_values v JOIN friends f ON f.id=v.friend_id JOIN rt_stores s ON s.line_account_id=f.line_account_id WHERE s.id=NEW.store_id AND f.line_platform_user_id=NEW.line_uid AND v.field_id='fixed-anniversary' LIMIT 1), 'seatPreference',(SELECT v.value FROM friend_field_values v JOIN friends f ON f.id=v.friend_id JOIN rt_stores s ON s.line_account_id=f.line_account_id WHERE s.id=NEW.store_id AND f.line_platform_user_id=NEW.line_uid AND v.field_id='fixed-seat_preference' LIMIT 1), 'courseId',NEW.course_id,'courseAllergens',json(COALESCE((SELECT allergens_json FROM rt_menu_items WHERE id=NEW.course_id AND store_id=NEW.store_id),'[]')),'capturedAt',NEW.created_at) WHERE id=NEW.id; END;

DROP TRIGGER rt_reservation_event_insert;
CREATE TRIGGER rt_reservation_event_insert AFTER INSERT ON rt_reservations WHEN NEW.status IN('confirmed','seated','visited') BEGIN INSERT OR IGNORE INTO rt_reservation_events(id,reservation_id,store_id,event_type,reservation_version,occurred_at,request_id,line_account_id,friend_id,payload_json) SELECT 'rt:'||NEW.id||':'||NEW.customer_version||':restaurant.reservation.created',NEW.id,NEW.store_id,'restaurant.reservation.created',NEW.customer_version,strftime('%Y-%m-%dT%H:%M:%fZ','now'),NEW.id||':'||NEW.customer_version,s.line_account_id, (SELECT id FROM friends WHERE line_account_id=s.line_account_id AND line_platform_user_id=NEW.line_uid), json_object('reservationId',NEW.id,'storeId',NEW.store_id,'startsAt',NEW.starts_at,'endsAt',NEW.ends_at,'status',NEW.status,'guestCount',NEW.guest_count) FROM rt_stores s WHERE s.id=NEW.store_id; END;

DROP TRIGGER rt_reservation_event_update;
CREATE TRIGGER rt_reservation_event_update AFTER UPDATE OF customer_version ON rt_reservations WHEN NEW.customer_version>OLD.customer_version BEGIN INSERT OR IGNORE INTO rt_reservation_events(id,reservation_id,store_id,event_type,reservation_version,occurred_at,request_id,line_account_id,friend_id,payload_json) SELECT 'rt:'||NEW.id||':'||NEW.customer_version||':'|| CASE WHEN NEW.departed_at IS NOT OLD.departed_at THEN CASE WHEN NEW.departed_at IS NULL THEN 'restaurant.departure_undone' ELSE 'restaurant.departed' END WHEN NEW.status IN('cancelled','no_show') AND NEW.status IS NOT OLD.status THEN 'restaurant.reservation.cancelled' WHEN NEW.status='visited' AND OLD.status<>'visited' THEN 'restaurant.arrived' WHEN OLD.status IN('visited','seated') AND NEW.status='confirmed' THEN 'restaurant.arrival_undone' WHEN OLD.status='pending' AND NEW.status='confirmed' THEN 'restaurant.reservation.created' ELSE 'restaurant.reservation.changed' END, NEW.id,NEW.store_id, CASE WHEN NEW.departed_at IS NOT OLD.departed_at THEN CASE WHEN NEW.departed_at IS NULL THEN 'restaurant.departure_undone' ELSE 'restaurant.departed' END WHEN NEW.status IN('cancelled','no_show') AND NEW.status IS NOT OLD.status THEN 'restaurant.reservation.cancelled' WHEN NEW.status='visited' AND OLD.status<>'visited' THEN 'restaurant.arrived' WHEN OLD.status IN('visited','seated') AND NEW.status='confirmed' THEN 'restaurant.arrival_undone' WHEN OLD.status='pending' AND NEW.status='confirmed' THEN 'restaurant.reservation.created' ELSE 'restaurant.reservation.changed' END, NEW.customer_version,strftime('%Y-%m-%dT%H:%M:%fZ','now'),NEW.id||':'||NEW.customer_version,s.line_account_id, (SELECT id FROM friends WHERE line_account_id=s.line_account_id AND line_platform_user_id=NEW.line_uid), json_object('reservationId',NEW.id,'storeId',NEW.store_id,'startsAt',NEW.starts_at,'endsAt',NEW.ends_at,'status',NEW.status,'guestCount',NEW.guest_count,'departedAt',NEW.departed_at,'previousVersion',OLD.customer_version, 'scheduleChanged',NEW.starts_at IS NOT OLD.starts_at OR NEW.ends_at IS NOT OLD.ends_at OR NEW.guest_count IS NOT OLD.guest_count) FROM rt_stores s WHERE s.id=NEW.store_id; END;

DROP TRIGGER rt_seat_waitlist_registration;
CREATE TRIGGER rt_seat_waitlist_registration BEFORE INSERT ON rt_seat_waitlist BEGIN SELECT CASE WHEN julianday(NEW.starts_at)<=julianday('now','+1 hour') THEN RAISE(ABORT,'waitlist_registration_closed') WHEN ((SELECT COUNT(*) FROM booking_waitlist w WHERE w.line_account_id=(SELECT line_account_id FROM rt_stores WHERE id=NEW.store_id) AND w.status IN ('waiting','invited') AND (w.friend_id=(SELECT id FROM friends WHERE line_platform_user_id=NEW.line_uid AND line_account_id=(SELECT line_account_id FROM rt_stores WHERE id=NEW.store_id)) OR (w.booking_customer_id IS NOT NULL AND w.booking_customer_id=NULL))) + (SELECT COUNT(*) FROM rt_seat_waitlist w JOIN rt_stores s ON s.id=w.store_id WHERE s.line_account_id=(SELECT line_account_id FROM rt_stores WHERE id=NEW.store_id) AND w.status IN ('waiting','invited') AND (w.line_uid=NEW.line_uid OR (NEW.line_uid IS NULL AND w.identity_key=NEW.identity_key))))>=3 THEN RAISE(ABORT,'waitlist_limit') END; END;

DROP TRIGGER rt_waitlist_invite_event;
CREATE TRIGGER rt_waitlist_invite_event AFTER UPDATE OF status ON rt_seat_waitlist WHEN NEW.status='invited' AND OLD.status='waiting' BEGIN INSERT OR IGNORE INTO rt_reservation_events(id,store_id,event_type,reservation_version,occurred_at,request_id,line_account_id,friend_id,payload_json) SELECT 'rt-waitlist:'||NEW.id||':'||NEW.notification_retry_key,NEW.store_id,'restaurant.waitlist.invited',0,NEW.invited_at,NEW.notification_retry_key,s.line_account_id, (SELECT id FROM friends WHERE line_account_id=s.line_account_id AND line_platform_user_id=NEW.line_uid), json_object('waitlistId',NEW.id,'storeId',NEW.store_id,'startsAt',NEW.starts_at,'holdExpiresAt',NEW.hold_expires_at) FROM rt_stores s WHERE s.id=NEW.store_id; END;

DROP TRIGGER rt_walkin_arrival_event;
CREATE TRIGGER rt_walkin_arrival_event AFTER INSERT ON rt_seat_visit_marks WHEN NEW.kind='visited' AND NEW.undone_at IS NULL BEGIN INSERT OR IGNORE INTO rt_reservation_events(id,reservation_id,store_id,event_type,reservation_version,occurred_at,request_id,line_account_id,friend_id,payload_json) SELECT 'rt:'||r.id||':'||r.customer_version||':restaurant.arrived',r.id,r.store_id,'restaurant.arrived',r.customer_version,NEW.marked_at,COALESCE(NEW.request_id,NEW.id),s.line_account_id,(SELECT id FROM friends WHERE line_account_id=s.line_account_id AND line_platform_user_id=r.line_uid),json_object('reservationId',r.id,'storeId',r.store_id,'startsAt',r.starts_at,'endsAt',r.ends_at,'status',r.status,'guestCount',r.guest_count) FROM rt_reservations r JOIN rt_stores s ON s.id=r.store_id WHERE r.id=NEW.reservation_id AND r.status IN('visited','seated'); END;
